  function searchRoots(node) {
    let list = [];
    if (node.shadowRoot) {
      list.push(node.tagName);
      list.push(...searchRoots(node.shadowRoot));
    }
    for (const child of node.children || []) {
      list.push(...searchRoots(child));
    }
    return list;
  }
  return [...new Set(searchRoots(document.body))];
});
