const result = await browserjs(tabId, () => {
  function findInShadow(root) {
    let results = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
    let n;
    while (n = walker.nextNode()) {
      if (n.shadowRoot) {
        results.push({ tag: n.tagName, id: n.id, inner: n.shadowRoot.innerHTML.slice(0, 200) });
        results = results.concat(findInShadow(n.shadowRoot));
      }
    }
    return results;
  }
  return findInShadow(document.body);
});
console.log(result);

