const tabId = 1962625065;
const detailedCards = await browserjs(tabId, () => {
  // Find all listing elements
  const cards = Array.from(document.querySelectorAll('a[href*="/vehicledetail/"]'))
    .filter(a => a.querySelector('h2') || a.parentElement.querySelector('h2'))
    .map(a => {
      const container = a.closest('.vehicle-card, .shop-srp-listings__listing-container') || a.parentElement.parentElement;
      return {
        title: a.textContent.trim(),
        href: a.href,
        allText: container ? container.innerText.split('\n').map(t => t.trim()).filter(Boolean) : []
      };
    });
  // Deduplicate by href
  const seen = new Set();
  const unique = [];
  for (const c of cards) {
    if (!seen.has(c.href)) {
      seen.add(c.href);
      unique.push(c);
    }
  }
  return unique.slice(0, 10);
});
console.log(JSON.stringify(detailedCards, null, 2));

